"""Weekly timesheet rows, one per worker."""

from typing import List, Tuple
from hourglass.schedule import worker_minutes
from hourglass.models import Shift
from collections import Counter

def check_shifts(shifts: List[Shift]) -> None:
    """Refuse an empty list or a nameless shift."""
    if not shifts:
        raise ValueError("no shifts given")
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("blank worker name")

def timesheet_line(
    name: str, count: int, minutes: int
) -> str:
    """Name, shift count and hours to one decimal place."""
    hours = minutes / 60
    return f"{name}: {count} shifts, {hours:.1f} hours"

def ranked_minutes(
    shifts: List[Shift]
) -> List[Tuple[str, int]]:
    """Worker and minutes, most first, ties by name."""
    pairs = worker_minutes(shifts).items()
    return sorted(
        pairs, key=lambda pair: (-pair[1], pair[0])
    )

def timesheet_lines(shifts: List[Shift]) -> List[str]:
    """One line per worker, busiest first."""
    check_shifts(shifts)
    counts = Counter(shift.worker for shift in shifts)
    return [
        timesheet_line(name, counts[name], total)
        for name, total in ranked_minutes(shifts)
    ]

