# owner: platform

import unittest
from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span

def make_shift(worker, weekday, start, stop):
    return Shift(worker, weekday, Span(start, stop))

class TimesheetTests(unittest.TestCase):
    def test_busiest_first_with_hours_to_one_decimal(self):
        shifts = [
            make_shift("Quill", "mon", 540, 990),
            make_shift("Brisa", "mon", 540, 1080),
            make_shift("Brisa", "tue", 540, 1080),
            make_shift("Odell", "wed", 600, 900)
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Brisa: 2 shifts, 18.0 hours",
                "Quill: 1 shifts, 7.5 hours",
                "Odell: 1 shifts, 5.0 hours"
            ]
        )

    def test_rounds_to_one_decimal(self):
        shifts = [make_shift("Brisa", "mon", 540, 640)]
        self.assertEqual(
            timesheet_lines(shifts),
            ["Brisa: 1 shifts, 1.7 hours"]
        )

    def test_equal_hours_sort_by_name(self):
        shifts = [
            make_shift("Zed", "mon", 540, 600),
            make_shift("Anna", "mon", 540, 600)
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Anna: 1 shifts, 1.0 hours",
                "Zed: 1 shifts, 1.0 hours"
            ]
        )

    def test_empty_list_is_an_error(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_name_is_an_error(self):
        for name in ("", "   "):
            with self.subTest(name=name):
                shifts = [make_shift(name, "mon", 540, 600)]
                with self.assertRaises(ValueError):
                    timesheet_lines(shifts)
